    pub fn generate_and_execute_batch<I>(&self, paths: I, buffer_output: bool) -> ExitCode
    where
        I: Iterator<Item = PathBuf>,
    {
        let mut paths: Vec<_> = paths.collect();
        paths.sort();

        if paths.is_empty() {
            return ExitCode::Success;
        }

        let max_command_length = max_batch_command_length();
        let mut results = Vec::new();

        let mut paths = paths.into_iter().peekable();
        while paths.peek().is_some() {
            let mut cmd = Command::new(self.args[0].generate("", None));
            cmd.stdin(Stdio::inherit());
            cmd.stdout(Stdio::inherit());
            cmd.stderr(Stdio::inherit());

            // Keep track of the total length of the generated command, so that we don't exceed
            // the maximum argument length supported by the OS/shell.
            let mut cmd_length = self.args[0].generate("", None).len();
            let mut has_path = false;

            for arg in &self.args[1..] {
                if arg.has_tokens() {
                    // A single `Tokens` is expected, so we can directly consume the
                    // (remaining) iterator until the maximum command length is reached.
                    while let Some(path) = paths.peek() {
                        let path_arg =
                            arg.generate(strip_current_dir(path), self.path_separator.as_deref());
                        let arg_length = path_arg.len() + 1;

                        // Always add at least one path per batch, even if it exceeds the
                        // maximum command length, to guarantee progress.
                        if has_path && cmd_length + arg_length > max_command_length {
                            break;
                        }

                        cmd.arg(path_arg);
                        cmd_length += arg_length;
                        has_path = true;
                        paths.next();
                    }
                } else {
                    let fixed_arg = arg.generate("", None);
                    cmd_length += fixed_arg.len() + 1;
                    cmd.arg(fixed_arg);
                }
            }

            if has_path {
                results.push(execute_command(cmd, &Mutex::new(()), buffer_output));
            } else {
                break;
            }
        }

        merge_exitcodes(results)
    }
}

/// Determine the maximum length (in bytes) that a batch command's arguments should not exceed,
/// leaving some room for the executable name, environment variables and other overhead.
#[cfg(all(unix, not(target_os = "redox")))]
fn max_batch_command_length() -> usize {
    let arg_max = unsafe { libc::sysconf(libc::_SC_ARG_MAX) };
    if arg_max <= 0 {
        // Could not be determined; fall back to a conservative default.
        return 32 * 1024;
    }
    // Leave some headroom for environment variables and other overhead that the shell/OS
    // will also count against the argument length limit.
    (arg_max as usize).saturating_sub(2048).max(4096)
}

#[cfg(not(all(unix, not(target_os = "redox"))))]
fn max_batch_command_length() -> usize {
    32 * 1024
}
